def protocol_handlers(cls, protocol_version=None):
    # Check if a protocol version was passed in
    if protocol_version is not None:
        # Ensure the protocol version is passed in as a tuple
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol version must be passed as a tuple")

        # Check if the specified protocol version is supported
        supported_versions = {(3, 7), (3, 6), (3, 5), (3, 4), (3, 3)}
