def unit_of_work(metadata=None, timeout=None):
    # Use the default timeout if not provided
    if timeout is None:
        timeout = float(config.get("dbms.transaction.timeout"))

    # Decorate the function with the unit of work metadata and timeout
    def wrap(function):
        def inner(*args, **kwargs):
            with unit_of_work(metadata, timeout)(function):
                return function(*args, **kwargs)
        return inner
    return wrap

