class Memoize(object):
    def __init__(self, cache, key=None, lock=None):
        self.cache = cache
        self.key = key
        self.lock = lock

    def __call__(self, f):
        def wrapper(*args, **kwargs):
            key = self.key(*args, **kwargs)
            if key in self.cache:
                return self.cache[key]
            else:
                with self.lock:
                    value = f(*args, **kwargs)
                    self.cache[key] = value
                return value
        return wrapper

