                result = func(*args, **kwargs)
                cache[key] = result
                return result
        return wrapped_func
    return wrapper

def lru_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = dict()
        def wrapped(*args):
            key = (args, typed)
            if key in cache:
                return cache[key]
            result = func(*args)
            cache[key] = result
            return result
        return wrapped
    return wrapper

