def validate_inventory(self, inventory, extract_spec_version=False):
    """Validate the given inventory.

    If extract_spec_version is True, it will look at the type value to determine
    the specification version. If there is no type value or it is not valid, it
    will be based on the version given in self.spec_version.
    """
    # Check that the inventory is a dict
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dict")

    # Check that the inventory has the required fields
    required_fields = ["title", "type", "license", "version", "components"]
    for field in required_fields:
        if field not in inventory:
            raise ValueError(f"Inventory is missing required field: {field}")

    # Check that the version field is a string
    if not isinstance(inventory["version"], str):
        raise ValueError("Version field must be a string")

    # Check that the license field is a string
    if not isinstance(inventory["license"], str):
        raise ValueError("License field must be a string")

    # Check that the type field is a string
    if not isinstance(inventory["type"], str):
        raise ValueError("Type field must be a string")

    # Check that the components field is a list
    if not isinstance(inventory["components"], list):
        raise ValueError("Components field must be a list")

    # If extract_spec_version is True, check that the type value is valid and
    # extract the specification version
    if extract_spec_version:
        # Check that the type value is valid
        if inventory["type"] not in ["openapi2.0", "openapi3.0"]:
            raise ValueError("Invalid type value")

        # Extract the specification version
        if inventory["type"] == "openapi2.0":
            self.spec_version = "2.0"
        else:
            self.spec_version = "3.0"

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.
    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that the versions match
    if self.version != prior.version:
        raise ValueError("The versions of the inventory data do not match")

    # Check that the lists have the same length
    if len(self.items) != len(prior.items):
        raise ValueError("The number of items does not match between the two inventory versions")

    # Check that the item names and quantities are the same
    for item in self.items:
        if item.name != prior.items[item.name].name:
            raise ValueError("The inventory items are not the same between the two versions")
        if item.quantity != prior.items[item.name].quantity:
            raise ValueError("The quantities of the inventory items do not match between the two versions")

    # Check that the lists of expired items are the same
    for expired_item in self.expired_items:
        if expired_item not in prior.expired_items:
            raise ValueError("The expired items are not the same between the two inventory versions")

    # Check that the lists of discontinued items are the same
    for discontinued_item in self.discontinued_items:
        if discontinued_item not in prior.discontinued_items:
            raise ValueError("The discontinued items are not the same between the two inventory versions")

    # Check that the lists of items with non-conforming quantities are the same
    for item in self.items_with_nonconforming_quantities:
        if item not in prior.items_with_nonconforming_quantities:
            raise ValueError("The items with non-conforming quantities are not the same between the two inventory versions")

    # Check that the lists of items with non-conforming expiration dates are the same
    for item in self.items_with_nonconforming_expiration_dates:
        if item not in prior.items_with_nonconforming_expiration_dates:
            raise ValueError("The items with non-conforming expiration dates are not the same between the two inventory versions")

