def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == "flat":
        result = ""
        for piece in pieces:
            result += piece
        return result
    elif style == "numbered":
        result = ""
        for i, piece in enumerate(pieces):
            result += str(i + 1) + ". " + piece + "\n"
        return result
    elif style == "bulleted":
        result = ""
        for i, piece in enumerate(pieces):
            result += " * " + piece + "\n"
        return result
    else:
        raise ValueError(f"Invalid style: {style}")

