def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    # Determine the appropriate regular expression to use based on the platform
    if platform == 'this':
        platform = sys.platform

    if platform == 'posix':
        pattern = r'(\s+|"([^"\\]*(\\.)?)*")'
    elif platform == 'windows/cmd':
        pattern = r'(\s+|^["](?:[^"\\]|\\.)|[^"])*?(?<!\\)["|\\]'
    else:
        pattern = r'(\s+)'

    # Split the string on the regular expression
    return re.split(pattern, s)

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    match = re.search(r"(\d+) ([^\s]+)", frequency)
    if not match:
        raise ValueError(f"Invalid frequency: {frequency}")
    amount = int(match.group(1))
    unit = match.group(2)
    if unit == "days":
        return datetime.timedelta(days=amount)
    elif unit == "weeks":
        return datetime.timedelta(weeks=amount)
    elif unit == "months":
        return datetime.timedelta(days=amount * 30)
    elif unit == "years":
        return datetime.timedelta(days=amount * 365)
    else:
        raise ValueError(f"Invalid unit of time: {unit}")

