def validate_from_content(cls, spec_content=None):
    if not spec_content:
        raise IRValidatorException("spec_content cannot be empty")

    # Load the spec as a dictionary
    spec = yaml.safe_load(spec_content)

    # Check if the spec has the required fields
    for field in ["name", "version", "services"]:
        if field not in spec:
            raise IRValidatorException(f"spec is missing required field: {field}")

    # Check if the spec has any unrecognized fields
    extra_fields = set(spec.keys()) - {"name", "version", "services"}
    if extra_fields:
        raise IRValidatorException(
            f"spec has unrecognized fields: {', '.join(extra_fields)}"
        )

    # Check if the services field is valid
    if not isinstance(spec["services"], list):
        raise IRValidatorException(
            "services field must be a list of service definitions"
        )

    # Check if each service definition is valid
    for service in spec["services"]:
        if not isinstance(service, dict):
            raise IRValidatorException("invalid service definition")

        # Check if the service definition has the required fields
        for field in ["name", "image", "ports"]:
            if field not in service:
                raise IRValidatorException(f"service is missing required field: {field}")

        # Check if the service definition has any unrecognized fields
        extra_fields = set(service.keys()) - {"name", "image", "ports"}
        if extra_fields:
            raise IRValidatorException(
                f"service has unrecognized fields: {', '.join(extra_fields)}"
            )

    # Check if the version field is a valid SemVer string
    version = spec["version"]
    if not SEMVER_REGEX.match(version):
        raise IRValidatorException(f"version must be a valid SemVer string: {version}")

    # Return the validated spec
    return spec

