        for key, value in extra_vars:
            vars_dict[key] = value

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    ansible_args = ansible_args or {}
    extra_vars = extra_vars or {}
    ansible_args["inventory"] = ir_plugin.load_ansible_inventory(ir_workspace, playbook_path)
    ansible_args["extra-vars"] = extra_vars
    ansible_args["verbose"] = verbose
    ansible_args["playbook"] = playbook_path
    ansible_args["connection"] = "local"
    ansible_run_process(ansible_args)

def _convert_non_cli_args(self, parser_name, values_dict: Dict[str, str]) -> None:
    """
    By default, all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Cast values to correct types based on the parser
    for key, value in values_dict.items():
        if key in self.parser[parser_name].option_strings:
            option_type = self.parser[parser_name].get_option(key).type
            if option_type == bool:
                values_dict[key] = value.lower() == "true"
            elif option_type == int:
                values_dict[key] = int(value)
            elif option_type == float:
                values_dict[key] = float(value)

    return None

def get_plugin_spec_flatten_dict(plugin_dir):
    spec = json.load(open(os.path.join(plugin_dir, "plugin.json")))
    flattened_spec = {}
    for key, value in spec.items():
        if isinstance(value, dict):
            for inner_key, inner_value in value.items():
                flattened_spec[f"{key}.{inner_key}"] = inner_value
        else:
            flattened_spec[key] = value
    return flattened_spec

def inject_config():
    import os

    # Check if the config path environment variable is defined
    if 'CONFIG_PATH' not in os.environ:
        # Set the config path environment variable if it is undefined
        os.environ['CONFIG_PATH'] = '/path/to/config'

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
